import React, { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  ComposableMap,
  Geographies,
  Geography,
  Sphere,
  Graticule,
} from "react-simple-maps";
import { buildVisitsByIso } from "../../lib/countryCodes";

const GEO_URL =
  "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json";

function getIso(geo) {
  return (
    geo.properties?.ISO_A2 ||
    geo.properties?.iso_a2 ||
    geo.properties?.ISO_A2_EH ||
    null
  );
}

function fillForVisits(visits, max) {
  if (!visits || max <= 0) return "rgba(255, 255, 255, 0.05)";
  const t = Math.min(1, visits / max);
  const alpha = 0.12 + t * 0.78;
  return `rgba(43, 216, 255, ${alpha})`;
}

export default function WorldMapHeatmap({ countries }) {
  const { t } = useTranslation();
  const [tooltip, setTooltip] = useState(null);
  const visitsByIso = useMemo(() => buildVisitsByIso(countries), [countries]);
  const maxVisits = useMemo(
    () => Math.max(...Object.values(visitsByIso), 1),
    [visitsByIso]
  );

  return (
    <div className="stats-map-wrap">
      {tooltip && (
        <div
          className="stats-map-tooltip"
          style={{ left: tooltip.x, top: tooltip.y }}
        >
          <strong>{tooltip.iso}</strong>
          <span>{t("stats.map_visits", { count: tooltip.visits })}</span>
        </div>
      )}
      <ComposableMap
        className="stats-map"
        projectionConfig={{ scale: 145, center: [0, 12] }}
      >
        <Sphere className="stats-map-sphere" stroke="rgba(43, 216, 255, 0.12)" />
        <Graticule className="stats-map-graticule" stroke="rgba(255,255,255,0.04)" />
        <Geographies geography={GEO_URL}>
          {({ geographies }) =>
            geographies.map((geo) => {
              const iso = getIso(geo);
              const visits = iso ? visitsByIso[iso] : 0;
              return (
                <Geography
                  key={geo.rsmKey}
                  geography={geo}
                  fill={fillForVisits(visits, maxVisits)}
                  stroke="rgba(255, 255, 255, 0.12)"
                  strokeWidth={0.4}
                  style={{
                    default: { outline: "none" },
                    hover: {
                      fill: visits
                        ? "rgba(43, 216, 255, 0.95)"
                        : "rgba(255, 255, 255, 0.12)",
                      outline: "none",
                      cursor: visits ? "pointer" : "default",
                    },
                    pressed: { outline: "none" },
                  }}
                  onMouseEnter={(evt) => {
                    if (!iso || !visits) return;
                    const rect = evt.currentTarget
                      .closest(".stats-map-wrap")
                      ?.getBoundingClientRect();
                    if (!rect) return;
                    setTooltip({
                      iso,
                      visits,
                      x: evt.clientX - rect.left + 12,
                      y: evt.clientY - rect.top - 8,
                    });
                  }}
                  onMouseLeave={() => setTooltip(null)}
                />
              );
            })
          }
        </Geographies>
      </ComposableMap>
    </div>
  );
}
